#!/usr/bin/env python3
"""Overdue fee statements: python3 fees.py INPUT_DIR OUTPUT_FILE"""
import configparser
import csv
import json
import os
import re
import sys
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal

WEEKDAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]


def patron_key(s):
    digits = re.sub(r"\D", "", s or "")
    return int(digits) if digits else None


def cents(s):
    return int((Decimal(s.strip()) * 100).to_integral_value())


def parse_date(s):
    return date.fromisoformat(s.strip())


def parse_offset(s):
    s = s.strip()
    m = re.fullmatch(r"([+-])(\d{1,2}):?(\d{2})", s)
    sign = -1 if m.group(1) == "-" else 1
    return sign * (int(m.group(2)) * 60 + int(m.group(3)))  # minutes


def parse_instant(s):
    """ISO 8601 instant -> naive UTC datetime."""
    s = s.strip()
    m = re.fullmatch(r"(\d{4}-\d\d-\d\d)[T ](\d\d):(\d\d)(?::(\d\d)(?:\.\d+)?)?\s*(Z|z|[+-]\d\d:?\d\d)?", s)
    d = parse_date(m.group(1))
    dt = datetime(d.year, d.month, d.day, int(m.group(2)), int(m.group(3)), int(m.group(4) or 0))
    z = m.group(5)
    if z and z not in "Zz":
        dt -= timedelta(minutes=parse_offset(z))
    return dt


def read_text(path):
    with open(path, encoding="utf-8-sig", newline="") as f:
        return f.read()


def read_csv(path):
    text = read_text(path)
    rows = list(csv.DictReader(text.splitlines()))
    out = []
    for r in rows:
        out.append({(k or "").strip().lower(): (v or "").strip() for k, v in r.items() if k is not None})
    return out


def load_policy(path):
    cp = configparser.RawConfigParser(delimiters=("=",), comment_prefixes=("#",), inline_comment_prefixes=None,
                                      interpolation=None)
    cp.read_string(read_text(path))
    pol = {"items": {}, "cats": {}}
    pol["library"] = cp.get("statement", "library").strip()
    pol["start"] = parse_date(cp.get("statement", "period_start"))
    pol["end"] = parse_date(cp.get("statement", "period_end"))
    off = parse_offset(cp.get("clock", "offset")) if cp.has_section("clock") and cp.has_option("clock", "offset") else 0
    changes = []
    if cp.has_section("clock") and cp.has_option("clock", "changes"):
        for part in cp.get("clock", "changes").split(";"):
            part = part.strip()
            if not part:
                continue
            inst, o = part.split(None, 1)
            changes.append((parse_instant(inst), parse_offset(o)))
        changes.sort()
    pol["offset"] = off
    pol["changes"] = changes
    for sec in cp.sections():
        low = sec.lower()
        if low.startswith("item:"):
            g = lambda k: cp.get(sec, k).strip()
            pol["items"][low[5:].strip()] = {
                "name": sec[5:].strip(),
                "loan_days": int(g("loan_days")), "renewals": int(g("renewals")),
                "grace": int(g("grace_days")), "daily": cents(g("daily")), "loan_cap": cents(g("loan_cap")),
            }
        elif low.startswith("category:"):
            cap = cp.get(sec, "statement_cap").strip()
            ex = cp.get(sec, "exempt").strip() if cp.has_option(sec, "exempt") else ""
            pol["cats"][low[9:].strip()] = {
                "name": sec[9:].strip(),
                "cap": None if cap.lower() == "none" else cents(cap),
                "discount": int(cp.get(sec, "discount").strip() or 0),
                "exempt": {x.strip().lower() for x in ex.split(",") if x.strip()},
            }
    return pol


def local_from_instant(pol, utc):
    off = pol["offset"]
    for inst, o in pol["changes"]:
        if inst <= utc:
            off = o
        else:
            break
    return utc + timedelta(minutes=off)


def load_events(indir, pol):
    exdir = os.path.join(indir, "exports")
    events = {}
    for name in sorted(os.listdir(exdir)):
        if not (name.endswith(".csv") or name.endswith(".jsonl")):
            continue
        path = os.path.join(exdir, name)
        recs = []
        if name.endswith(".csv"):
            for r in read_csv(path):
                if not r.get("event"):
                    continue
                r["local"] = datetime.strptime(r["time"], "%Y-%m-%d %H:%M") if r.get("time") else None
                recs.append(r)
        else:
            for line in read_text(path).splitlines():
                line = line.strip()
                if not line:
                    continue
                o = json.loads(line)
                r = {k.lower(): ("" if v is None else str(v).strip()) for k, v in o.items()}
                if not r.get("event"):
                    continue
                r["local"] = local_from_instant(pol, parse_instant(r["at"])) if r.get("at") else None
                recs.append(r)
        for r in recs:
            r["type"] = r.get("type", "").lower()
            r["via"] = r.get("via", "").lower()
            events.setdefault(r["event"], r)
    return events


class Calendar:
    def __init__(self, indir, branches):
        self.open_days = {}
        for b in branches:
            days = {d.strip().lower()[:3] for d in b["open_days"].split()}
            self.open_days[b["branch"].lower()] = {WEEKDAYS.index(d) for d in days if d in WEEKDAYS}
        self.rows = {}
        for r in read_csv(os.path.join(indir, "calendar.csv")):
            ds = r["date"]
            if ".." in ds:
                a, b = ds.split("..")
            else:
                a = b = ds
            self.rows.setdefault(r["branch"].strip().lower(), []).append(
                (parse_date(a), parse_date(b), r["status"].strip().lower()))
        self.cache = {}

    def is_open(self, branch, day):
        key = (branch.lower(), day)
        if key in self.cache:
            return self.cache[key]
        res = None
        for bkey in (branch.lower(), "*"):
            for a, b, st in self.rows.get(bkey, []):
                if a <= day <= b:
                    res = (st == "open")
            if res is not None:
                break
        if res is None:
            res = day.weekday() in self.open_days.get(branch.lower(), set())
        self.cache[key] = res
        return res

    def next_open(self, branch, day):
        """day itself if open, else the next open day."""
        for _ in range(3660):
            if self.is_open(branch, day):
                return day
            day += timedelta(days=1)
        return day


def main(indir, outfile):
    pol = load_policy(os.path.join(indir, "policy.ini"))
    branches = read_csv(os.path.join(indir, "branches.csv"))
    cal = Calendar(indir, branches)
    branch_ids = {b["branch"].lower(): b["branch"] for b in branches}

    patrons = {}
    for r in read_csv(os.path.join(indir, "patrons.csv")):
        patrons.setdefault(patron_key(r["patron"]), []).append(
            (parse_date(r["since"]), r["patron"], r["category"]))
    for v in patrons.values():
        v.sort(key=lambda x: x[0])

    def patron_row(pk, day):
        best = None
        for row in patrons.get(pk, []):
            if row[0] <= day:
                best = row
        return best

    def category(pk, day):
        row = patron_row(pk, day)
        return pol["cats"][row[2].strip().lower()] if row else None

    waivers = {}
    for r in read_csv(os.path.join(indir, "waivers.csv")):
        if r.get("status", "").strip().lower() != "active":
            continue
        v = r["value"].strip()
        waivers.setdefault(patron_key(r["patron"]), []).append(
            (r["loan"].strip(), None if v.lower() == "full" else cents(v)))

    events = load_events(indir, pol)
    cancelled = {e["target"] for e in events.values() if e["type"] == "void" and e.get("target")}
    live = [e for e in events.values() if e["type"] != "void" and e["event"] not in cancelled]

    checkouts = {}
    for e in live:
        if e["type"] == "checkout" and e["local"].date() <= pol["end"]:
            checkouts[e["loan"]] = e
    later = {}
    for e in live:
        if e["type"] in ("renew", "return") and e.get("loan") in checkouts:
            later.setdefault(e["loan"], []).append(e)

    loans = []
    for lid, co in checkouts.items():
        it = pol["items"][co["item_type"].strip().lower()]
        branch = branch_ids.get(co["branch"].lower(), co["branch"])
        cdate = co["local"].date()
        due = cal.next_open(branch, cdate + timedelta(days=it["loan_days"]))
        renewed = 0
        returned = None
        for ev in sorted(later.get(lid, []), key=lambda x: (x["local"], x["event"])):
            if ev["type"] == "renew":
                d = ev["local"].date()
                if d <= due and renewed < it["renewals"] and d <= pol["end"]:
                    renewed += 1
                    due = cal.next_open(branch, d + timedelta(days=it["loan_days"]))
            else:
                returned = ev["local"].date()
                if ev["via"] == "dropbox":
                    returned -= timedelta(days=1)
                break
        if returned is not None and returned < pol["start"]:
            continue
        out_at_end = returned is None or returned > pol["end"]
        endday = pol["end"] if out_at_end else returned
        overdue = 0
        d = due + timedelta(days=1)
        while d <= endday:
            if cal.is_open(branch, d):
                overdue += 1
            d += timedelta(days=1)
        if overdue == 0:
            continue
        pk = patron_key(co["patron"])
        charged = overdue if overdue > it["grace"] else 0
        base = charged * it["daily"]
        cat = category(pk, cdate)
        if it["name"].lower() in cat["exempt"]:
            base = 0
        base = min(base, it["loan_cap"])
        assessed = (base * (100 - cat["discount"]) + 50) // 100
        loans.append({
            "pk": pk, "loan": lid, "item": co.get("item", ""), "item_type": it["name"], "branch": branch,
            "checkout": cdate, "due": due, "returned": None if out_at_end else returned,
            "overdue_days": overdue, "charged_days": charged, "assessed": assessed,
        })

    by_patron = {}
    for l in loans:
        by_patron.setdefault(l["pk"], []).append(l)

    statements = []
    for pk in sorted(by_patron):
        ls = by_patron[pk]
        for l in ls:
            ws = [amt for (lid, amt) in waivers.get(pk, []) if lid == "*" or lid == l["loan"]]
            if any(a is None for a in ws):
                w = l["assessed"]
            else:
                w = min(sum(ws), l["assessed"])
            l["waived"] = w
            l["net"] = l["assessed"] - w
            l["capped"] = 0
        endrow = patron_row(pk, pol["end"])
        cat = pol["cats"][endrow[2].strip().lower()]
        if cat["cap"] is not None:
            excess = sum(l["net"] for l in ls) - cat["cap"]
            if excess > 0:
                order = sorted(ls, key=lambda l: (l["due"], l["loan"]), reverse=True)
                for l in order:
                    if excess <= 0:
                        break
                    take = min(excess, l["net"])
                    l["capped"] = take
                    excess -= take
        ls.sort(key=lambda l: (l["due"], l["loan"]))
        outloans = []
        for l in ls:
            l["billed"] = l["net"] - l["capped"]
            outloans.append({
                "loan": l["loan"], "item": l["item"], "item_type": l["item_type"], "branch": l["branch"],
                "checkout": l["checkout"].isoformat(), "due": l["due"].isoformat(),
                "returned": l["returned"].isoformat() if l["returned"] else None,
                "overdue_days": l["overdue_days"], "charged_days": l["charged_days"],
                "assessed": l["assessed"], "waived": l["waived"], "capped": l["capped"], "billed": l["billed"],
            })
        st = {"patron": endrow[1], "category": cat["name"], "loans": outloans}
        for k in ("assessed", "waived", "capped", "billed"):
            st[k] = sum(x[k] for x in outloans)
        statements.append(st)

    summary = []
    for b in branches:
        row = {"branch": b["branch"], "loans": 0, "charged_days": 0, "assessed": 0, "waived": 0, "capped": 0,
               "billed": 0}
        for l in loans:
            if l["branch"] == b["branch"]:
                row["loans"] += 1
                for k in ("charged_days", "assessed", "waived", "capped", "billed"):
                    row[k] += l[k]
        summary.append(row)

    result = {"library": pol["library"], "period": {"start": pol["start"].isoformat(), "end": pol["end"].isoformat()},
              "statements": statements, "branches": summary}
    parent = os.path.dirname(os.path.abspath(outfile))
    os.makedirs(parent, exist_ok=True)
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
